function d_auction(P,R){var tasks=P.tasks||[],robots=P.robots||3;var assign=tasks.map(function(t,i){var bids=[];for(var r=0;r<robots;r++)bids.push({robot:r,bid:+(t.value/(1+r*0.3+R()*0.2)).toFixed(2)});bids.sort(function(a,b){return b.bid-a.bid;});return{task:t.name,winner:bids[0].robot,winning_bid:bids[0].bid};});return{assignments:assign,tasks:tasks.length,robots:robots};}

