function d_provenance(P,R){function h(s){var x=0;for(var i=0;i<s.length;i++)x=(Math.imul(x,31)+s.charCodeAt(i))|0;return (x>>>0).toString(16);}var chain=[],prev='GENESIS';(P.steps||['design','simulate','review']).forEach(function(s){var cur=h(prev+':'+s);chain.push({step:s,hash:cur,prev:prev});prev=cur;});return{chain:chain,head:prev,verified:true};}

